ам/4-if-this-is-your-vibe MoneyBruno ../по-примерам/5-money-cant-buy-happiness MeWhenThree ../по-примерам/6-me-when-im MorningThree ../по-примерам/7-pov-my-morning-routine DaysVoice ../по-примерам/8-monday-to-sunday-voice)
ids=("$@"); [ ${#ids} -eq 0 ] && ids=(${(ko)OUT})
for id in $ids; do
  vo=false; [[ $id == Idea13AmyDay || $id == Idea16DearDiary || $id == Idea44NobodyTells || $id == Voice* || $id == WeekDays || $id == DaysVoice ]] && vo=true
  out="../готовые/идеи/${OUT[$id]}.mp4"; [[ -z ${OUT[$id]} ]] && out="../готовые/новые/$id.mp4"
  # render from a private copy of only the files this reel needs (the project folder sits in iCloud and may be offloaded)
  PUB="$TMPPUB/$id"; rm -rf "$PUB"; mkdir -p "$PUB/clips" "$PUB/audio" "$PUB/photos"
  node scripts/assets.mjs "$CFG" $id | while read f; do cp "public/$f" "$PUB/$f"; done
  r=$(npx remotion render src/index.ts $id "$out" --public-dir "$PUB" --codec h264 --crf 21 --timeout 180000 --concurrency 1 --props "{\"voiceover\":$vo}" 2>&1 | tail -3 | tr '\n' ' ')
  # strip the "Made with Remotion" comment and other container tags (no re-encode)
  B="$PWD/node_modules/@remotion/compositor-darwin-arm64"
  DYLD_LIBRARY_PATH="$B" "$B/ffmpeg" -v error -y -i "$out" -map_metadata -1 -c copy -movflags +faststart "$out.clean.mp4" </dev/null && mv "$out.clean.mp4" "$out"
  rm -rf "$PUB"
  echo "$id :: ${r[-150,-1]}"
done
echo ALLDONE
